-- DB-06: 回答の検証を共有テストベクタで確かめる（TS の validatePaintBytes と同じ結果になること）。
-- このファイルは scripts/genPaintVectorsSql.mjs が packages/core/test-vectors/paint-validation.json から生成する。手で編集しない。
begin;
select plan(18);

-- validate_paint → check_size の順に呼び、エラーコード（正常なら null）を返す（answers のトリガと同じ）
create or replace function pg_temp.answer_code(p_hex text, p_keys text[], p_size numeric, p_min numeric, p_max numeric)
returns text language plpgsql as $$
declare u boolean;
begin
  u := public.validate_paint(decode(substr(p_hex, 3), 'hex'), p_keys);
  perform public.check_size(u, p_size, p_min, p_max);
  return null;
exception when sqlstate 'P0001' then
  return sqlerrm;
end $$;

select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), null, '正常: AA を call 100%');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], 13, 13, 95.7), null, '正常: AA を s1 100%、size = min');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], 95.7, 13, 95.7), null, '正常: 混合と size = max');
select is(pg_temp.answer_code('\', array['check']::text[], null, null, null), null, '正常: check のみ');
select is(pg_temp.answer_code('\', array['check', 's1']::text[], 1, 1, 85.5), null, '正常: check と s1（bet）');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_length', '長さが 675');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_length', '長さが 677');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_value', '値が 21');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_illegal_key', '合法でないキー（check）');
select is(pg_temp.answer_code('\', array['check', 's1']::text[], null, 1, 85.5), 'paint_illegal_key', '合法でないキー（fold）');
select is(pg_temp.answer_code('\', array['check', 's1']::text[], null, 1, 85.5), 'paint_illegal_key', '合法でないキーと合計違反は合法キーの判定が先');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_sum', 'マスの合計が 15');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_sum', 'マスの合計が 25');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'paint_empty', '塗ったマスがない');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], 12.999, 13, 95.7), 'size_out_of_range', 's1 を含み size が min 未満');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], 95.701, 13, 95.7), 'size_out_of_range', 's1 を含み size が max 超');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], null, 13, 95.7), 'size_out_of_range', 's1 を含み size がない');
select is(pg_temp.answer_code('\', array['fold', 'call', 's1']::text[], 13, 13, 95.7), 'size_not_allowed', 's1 を含まないのに size がある');

select * from finish(true);
rollback;
